class DefinitionRestorationBrowserIT extends WorkbenchBrowserSupport {
    @Test void sourceAttributePresenceAndWholeDeletedItemDoNotUndoOtherChanges(){
        initial(9);open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");JsonNode source=doc.path("definitionDraft").path("sourceDocument").deepCopy();((ObjectNode)def.path("teachers").get(0)).put("displayName","Authored teacher");((ObjectNode)def.path("cohorts").get(0)).put("displayName","Authored class").putArray("availablePeriodIds");store("DEFINITION_DRAFT",doc);
        restore("Cohort","cohort-7a","availablePeriodIds");assertFalse(definition().path("cohorts").get(0).has("availablePeriodIds"));assertEquals("Authored class",definition().path("cohorts").get(0).path("displayName").asString());assertEquals("Authored teacher",definition().path("teachers").get(0).path("displayName").asString());
        doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();def=doc.withObject("definitionDraft").withObject("definition");JsonNode old=def.path("lessons").get(0).deepCopy();((tools.jackson.databind.node.ArrayNode)def.path("lessons")).remove(0);((tools.jackson.databind.node.ArrayNode)def.path("subjects")).remove(0);doc.withObject("definitionDraft").withArray("removedIdentities").addObject().put("ownerType","Lesson").put("id","lesson-math-1").put("hasSource",true);store("DEFINITION_DRAFT",doc);
        restore("Lesson","lesson-math-1","");assertTrue(definition().path("lessons").toString().contains(JSON.writeValueAsString(old)));assertEquals(1,definition().path("subjects").size());assertTrue(draft().path("issues").toString().contains("BLOCKING"));assertFalse(draft().path("removedIdentities").toString().contains("lesson-math-1"));assertEquals(source,draft().path("sourceDocument"));
        restore("Subject","math","");assertEquals(2,definition().path("subjects").size());assertFalse(draft().path("issues").toString().contains("BLOCKING"));assertEquals(source.path("initialDefinition"),storedWorkspaceDocument().path("initialDefinition"));
    }
    @Test void olderEffectiveDefaultsCatalogAndLineagePreserved(){
        initial(1);open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=doc.withObject("definitionDraft").withObject("definition");def.put("catalogVersion",9);((ObjectNode)def.path("cohorts").get(0)).put("maxDailyGaps",0).put("displayName","New name");def.putArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-gap").put("weight",8);store("DEFINITION_DRAFT",doc);JsonNode source=draft().path("sourceDocument").deepCopy();restore("Cohort","cohort-7a","maxDailyGaps");assertEquals(Integer.MAX_VALUE,definition().path("cohorts").get(0).path("maxDailyGaps").intValue());assertEquals("New name",definition().path("cohorts").get(0).path("displayName").asString());restore("Preference","soft.cohort-gap","weight");assertEquals(1,definition().path("softConstraintOverrides").size());assertEquals(0,definition().path("softConstraintOverrides").get(0).path("weight").intValue());restore("School","demo-school","softConstraintOverrides");assertEquals(4,definition().path("softConstraintOverrides").size());for(JsonNode row:definition().path("softConstraintOverrides"))assertEquals(row.path("constraintId").asString().equals("soft.teacher-gap")?2:0,row.path("weight").intValue());assertEquals(9,definition().path("catalogVersion").intValue());assertFalse(definition().has("basedOnRevision"));assertEquals(source,draft().path("sourceDocument"));
    }
    @Test void sourcePinsStayExpiredPersistentRoomReturnsAndCurrentExact()throws Exception{
        ObjectNode source=fixtures.validAcceptedDocument();ObjectNode lesson=(ObjectNode)source.path("acceptedBaseline").path("definition").path("lessons").get(0);lesson.put("periodLock","mon-1").put("roomLock","room-102");String revision=verifier.verify(new ImportDocuments(source.path("acceptedBaseline").path("definition"),null,null,ImportDocuments.ImportMode.INITIAL_DEFINITION)).definitionRevision();ObjectNode result=(ObjectNode)source.path("acceptedBaseline").path("result");result.put("inputRevision",revision);String timetable=timetableRevision(result,revision);result.put("timetableRevision",timetable);source.put("definitionRevision",revision).put("timetableRevision",timetable);((ObjectNode)source.path("acceptedBaseline").path("manifest")).put("inputRevision",revision).put("timetableRevision",timetable);((ObjectNode)source.path("acceptedBaseline").path("manifest")).withArray("locks").addObject().put("lessonId","lesson-math-1").put("periodLockOrigin","ATTEMPT_SCOPED").put("roomLockOrigin","PERSISTENT_POLICY");storeAccepted(source);workbench.open();open();JsonNode exact=draft().path("sourceDocument").deepCopy();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();ObjectNode edited=(ObjectNode)doc.path("definitionDraft").path("definition").path("lessons").get(0);edited.put("periodLock","mon-2").put("roomLock","room-101").put("displayName","Authored lesson");doc.withObject("definitionDraft").withObject("editingContext").withObject("authoredLocks").withObject("lesson-math-1").put("periodLock","mon-2");store("DEFINITION_DRAFT",doc);restore("Lesson","lesson-math-1","periodLock");assertFalse(definition().path("lessons").get(0).has("periodLock"));assertEquals("Authored lesson",definition().path("lessons").get(0).path("displayName").asString());assertEquals("room-101",definition().path("lessons").get(0).path("roomLock").asString());restore("Lesson","lesson-math-1","");assertFalse(definition().path("lessons").get(0).has("periodLock"));assertEquals("room-102",definition().path("lessons").get(0).path("roomLock").asString());assertEquals(exact,draft().path("sourceDocument"));for(var entry:exact.properties())assertEquals(entry.getValue(),storedWorkspaceDocument().path(entry.getKey()));
    }
    @Test void fieldRevertPreservesEqualUnselectedExceptionIntent(){
        initial(9);open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();ObjectNode group=doc.withObject("definitionDraft").withObject("editingContext").withObject("requirements").putObject("series-math-7a");group.put("seriesId","series-math-7a").put("subjectId","math").put("cohortId","cohort-7a").put("count",1).put("nextSequence",3);group.putObject("defaults").put("teacherId","teacher-alex");group.putArray("mixedFields");group.putObject("exceptions").putArray("lesson-math-1").add("teacherId");store("DEFINITION_DRAFT",doc);restore("Lesson","lesson-math-1","preferredRoomIds");assertTrue(draft().path("editingContext").path("requirements").path("series-math-7a").path("exceptions").path("lesson-math-1").toString().contains("teacherId"));assertEquals(3,draft().path("editingContext").path("requirements").path("series-math-7a").path("nextSequence").intValue());
    }
    @Test void requirementSourceDefaultsRetainExistingNativeOccurrencesAndCancellations(){
        initial(9);open();ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy(),draft=doc.withObject("definitionDraft"),group=draft.withObject("editingContext").withObject("requirements").putObject("series-math-7a");group.put("seriesId","series-math-7a").put("cohortId","cohort-7a").put("subjectId","math").put("count",1).put("nextSequence",9);group.putObject("defaults").put("teacherId","authored-default");group.putObject("exceptions").putArray("lesson-math-1").add("preferredRoomIds");group.putArray("mixedFields");store("DEFINITION_DRAFT",doc);JsonNode before=definition().deepCopy();restore("Series","series-math-7a","defaults.teacherId");assertEquals(before,definition());JsonNode context=draft().path("editingContext").path("requirements").path("series-math-7a");assertEquals("teacher-alex",context.path("defaults").path("teacherId").asString());assertTrue(context.path("exceptions").path("lesson-math-1").toString().contains("preferredRoomIds"));assertEquals(9,context.path("nextSequence").intValue());doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();((tools.jackson.databind.node.ArrayNode)doc.path("definitionDraft").path("definition").path("lessons")).remove(0);doc.withObject("definitionDraft").withObject("editingContext").withObject("requirements").remove("series-math-7a");store("DEFINITION_DRAFT",doc);before=definition().deepCopy();restore("Series","series-math-7a","");assertEquals(before,definition());assertEquals(0,draft().path("editingContext").path("requirements").path("series-math-7a").path("count").intValue());
    }
    @Test void browserPreviewCancelStaleStorageTransportNarrowAndRestart()throws Exception{
        initial(9);open();assertEquals(200,command("school",JSON.readTree("{\"schoolId\":\"demo-school\",\"displayName\":\"Authored name\"}"),null).status());workbench.reload();page().getByText("Restore source values",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();page().locator("#refresh-restoration").click();page().locator("#restoration-scope").waitFor();page().locator("#restoration-scope").selectOption(JSON.writeValueAsString(scope("School","demo-school","displayName")));String before=storedDocument();page().locator("#preview-restoration").click();page().locator("#restoration-preview-dialog").waitFor();assertEquals(before,storedDocument());page().locator("#cancel-restoration").click();assertEquals(before,storedDocument());page().locator("#preview-restoration").click();assertEquals(200,command("preferences",JSON.readTree("{\"constraintId\":\"soft.teacher-gap\",\"mode\":\"value\",\"weight\":4}"),null).status());String newer=storedDocument();page().locator("#confirm-restoration").click();workbench.awaitText("No restoration was committed");assertEquals(newer,storedDocument());page().locator("#cancel-restoration").click();page().locator("#refresh-restoration").click();workbench.expect("document.querySelector('#preview-restoration') && !document.querySelector('#preview-restoration').disabled");page().locator("#preview-restoration").click();withRejectedWorkspaceUpdates("NEW.lifecycle_state = 'DEFINITION_DRAFT'",()->{page().locator("#confirm-restoration").click();workbench.awaitText("No restoration was committed");assertEquals(newer,storedDocument());});page().locator("#cancel-restoration").click();page().route("**/api/definition-draft/restoration",route->route.abort());page().locator("#preview-restoration").click();page().locator("#confirm-restoration").click();workbench.awaitText("No restoration was committed");assertEquals(newer,storedDocument());page().unroute("**/api/definition-draft/restoration");page().locator("#cancel-restoration").click();for(int width:List.of(390,700)){workbench.viewport(width,844);workbench.expect("!document.querySelector('#restoration-scope') && document.documentElement.scrollWidth <= innerWidth");assertEquals(newer,storedDocument());}workbench.viewport(1280,800);page().locator("button[data-section='Review']").click();page().locator("#school-stay").click();page().locator("button[data-section='Review']").click();page().locator("#school-save-continue").click();page().locator("#confirm-restoration").click();workbench.expect("document.querySelector('#authoring-section h3')?.textContent === 'Review'");assertEquals("Demo School",definition().path("displayName").asString());assertEquals(4,definition().path("softConstraintOverrides").get(0).path("weight").intValue());String saved=storedDocument();workbench.reload();assertEquals(saved,storedDocument());try(var restarted=startRestartableWorkspace()){workbench.open(((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort());assertEquals(saved,storedDocument());}
    }
    @Test void emptyNewSourceAndInvalidTokenStateNeverMutate(){
        workbench.open();open();assertEquals(0,JSON.readTree(command("restoration/inspect",JSON.createObjectNode(),null).text()).path("choices").size());String before=storedDocument();assertEquals(409,command("restoration/preview",scope("School","new","displayName"),null).status());assertEquals(before,storedDocument());initial(9);open();assertEquals(200,command("rooms",JSON.readTree("{\"originalId\":\"\",\"item\":{\"id\":\"new-room\",\"displayName\":\"New\",\"capacity\":0,\"capabilityIds\":[]}}"),null).status());before=storedDocument();assertEquals(409,command("restoration/preview",scope("Room","new-room",""),null).status());assertEquals(before,storedDocument());ObjectNode request=scope("School","demo-school","displayName");JsonNode preview=JSON.readTree(command("restoration/preview",request,null).text());ObjectNode envelope=JSON.createObjectNode().put("token","invalid");envelope.set("request",request);assertEquals(409,command("restoration",envelope,null).status());assertEquals(before,storedDocument());envelope.set("token",preview.path("token"));assertEquals(412,command("restoration",envelope,"\"ws-0\"").status());assertEquals(before,storedDocument());store("INITIAL_DRAFT",storedWorkspaceDocument());before=storedDocument();assertEquals(409,command("restoration",envelope,null).status());assertEquals(before,storedDocument());
    }
    private void initial(int catalog){ObjectNode def=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy().put("catalogVersion",catalog);if(catalog<8)((ObjectNode)def.path("cohorts").get(0)).remove("curatorTeacherId");ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",def);store("INITIAL_DRAFT",doc);workbench.open();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private JsonNode draft(){return storedWorkspaceDocument().path("definitionDraft");}
    private JsonNode definition(){return draft().path("definition");}
    private ObjectNode scope(String type,String id,String field){return JSON.createObjectNode().put("type",type).put("id",id).put("field",field);}
    private void restore(String type,String id,String field){ObjectNode request=scope(type,id,field);String before=storedDocument();APIResponse response=command("restoration/preview",request,null);assertEquals(200,response.status(),response.text());assertEquals(before,storedDocument());JsonNode preview=JSON.readTree(response.text());ObjectNode envelope=JSON.createObjectNode();envelope.set("request",request);envelope.set("token",preview.path("token"));assertEquals(200,command("restoration",envelope,null).status());}
    private APIResponse command(String route,JsonNode body,String version){String base="http://localhost:"+port;JsonNode csrf=JSON.readTree(page().request().get(base+"/api/csrf").text());return page().request().post(base+"/api/definition-draft/"+route,RequestOptions.create().setHeader("Content-Type","application/json").setHeader("Origin",base).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()).setHeader("If-Match",version==null?"\"ws-"+storedVersion()+"\"":version).setData(JSON.writeValueAsString(body)));}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state,version=version+1,active_run_id=NULL,document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
    private String timetableRevision(JsonNode result,String revision)throws Exception{ObjectNode scope=JSON.createObjectNode().put("schemaVersion",1).put("schoolId",result.path("schoolId").asString()).put("inputRevision",revision);var ordered=new java.util.ArrayList<JsonNode>();result.path("timetable").path("assignments").forEach(ordered::add);ordered.sort(java.util.Comparator.comparing(item->item.path("lessonId").asString()));ordered.forEach(scope.putArray("assignments")::add);return "sha256:"+java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(CanonicalJson.bytes(scope)));}
}
